// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.screenimport timber.log.Timberimport com.roshan.persona.vision.core.ConfidenceTieredResultimport com.roshan.persona.vision.core.ConfidenceTierimport com.roshan.persona.vision.ocr.OcrEngineimport com.roshan.persona.vision.ocr.OcrResultimport com.roshan.persona.vision.ocr.OcrBlockimport com.roshan.persona.vision.ocr.BoundingBoximport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Screen Understanding Engine (Module 6 v4 — Step 6.6, v3 Elite Feature). * * The **Visual Screen Reader** — NOUS becomes the most capable on-device screen * reader on Android, beating Google TalkBack and Voice Access by combining * OCR + UI element detection + LLM summarization + emotional TTS. * * ## How it works (per strategy v3 §"Upgrade 1: Visual Screen Reader") * * ``` * Blind user: "NOUS, what's on my screen?" *   ↓ * 1. ScreenUnderstandingEngine captures screenshot via AccessibilityService *   ↓ * 2. OcrEngine extracts ALL text from the screenshot (< 500 ms) *   ↓ * 3. UiElementDetector finds buttons, icons, input fields with bounding boxes *   ↓ * 4. ScreenSummarizer (Module 4 LLM) generates: *    "You're on the WhatsApp chat with Mom. She sent you a photo 2 minutes ago. *     There's a reply button at the bottom. There are 3 unread notifications." *   ↓ * 5. Module 5 EmotionalTtsEngine reads it with WARM persona voice * ``` * * ## Why this beats TalkBack / Voice Access * *  - **Semantic understanding** — not just element tree reading. *    TalkBack: "Button, Send button, send button" *    NOUS: "There's a blue Send button at the bottom right." *  - **LLM-summarized context** — "You have 3 unread messages from Mom and Priya" *    instead of reading each notification. *  - **Works on ANY app** — including games, custom Canvas apps that don't *    expose accessibility trees. *  - **100% offline** — no cloud round-trip. Screen content NEVER leaves device. * * ## Privacy (per strategy v4 §"Privacy & Security") * *  - **Per-session consent required.** User sees a persistent notification: *    "NOUS is reading your screen. Tap to stop." *  - **Screenshots are NOT persisted.** Processed in RAM, immediately discarded. *  - **OCR text is NOT persisted** — only the summary is spoken via TTS. *  - **No screen content is logged or synced.** *  - **User can revoke consent anytime** by tapping the persistent notification. * * ## Testability * * Native dependencies are injected: *  - [ScreenshotCapturer] — wraps AccessibilityService (Module 10) *  - [UiElementDetector] — wraps ML Kit object detection (for buttons/icons) *  - [ScreenSummarizer] — wraps Module 4 LLM * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Upgrade 1: Visual Screen Reader</a> */class ScreenUnderstandingEngine(    private val screenshotCapturer: ScreenshotCapturer,    private val ocrEngine: OcrEngine,    private val uiElementDetector: UiElementDetector,    private val screenSummarizer: ScreenSummarizer,    private val dispatcher: CoroutineDispatcher,) {    /** True if screen reading is currently active (per-session consent). */    @Volatile    private var sessionActive: Boolean = false    /** True if user has granted per-session consent. */    @Volatile    private var consentGranted: Boolean = false    /**     * Start a screen reading session.     *     * Requires explicit user consent (shown as persistent notification).     *     * @return true if session started successfully.     */    fun startSession(): Boolean {        if (!screenshotCapturer.isAvailable()) {            Timber.tag(TAG).w("Accessibility service not available — cannot start screen reading.")            return false        }        consentGranted = true        sessionActive = true        Timber.tag(TAG).i("Screen reading session started (consent granted).")        return true    }    /**     * Stop the screen reading session + clear consent.     */    fun stopSession() {        sessionActive = false        consentGranted = false        Timber.tag(TAG).i("Screen reading session stopped.")    }    /**     * Read the current screen — captures screenshot, extracts text + UI elements,     * generates LLM summary, returns for TTS readout.     *     * @return the screen summary, or null if session not active or capture failed.     */    suspend fun readScreen(): ScreenUnderstandingResult? = withContext(dispatcher) {        if (!sessionActive || !consentGranted) {            Timber.tag(TAG).w("Cannot read screen — session not active or consent not granted.")            return@withContext null        }        val startTime = System.currentTimeMillis()        // 1. Capture screenshot.        val screenshot = try {            screenshotCapturer.capture()        } catch (t: Throwable) {            Timber.tag(TAG).e("Screenshot capture failed", t)            return@withContext null        }        if (screenshot == null) {            Timber.tag(TAG).w("Screenshot capture returned null.")            return@withContext null        }        // 2. OCR the screenshot.        val ocrResult = try {            ocrEngine.recognize(screenshot)        } catch (t: Throwable) {            Timber.tag(TAG).e("OCR failed on screenshot", t)            null        }        // 3. Detect UI elements (buttons, icons, input fields).        val uiElements = try {            uiElementDetector.detect(screenshot)        } catch (t: Throwable) {            Timber.tag(TAG).w("UI element detection failed — continuing with OCR only.", t)            emptyList()        }        // 4. Generate LLM summary.        val summary = try {            screenSummarizer.summarize(                ocrText = ocrResult?.value?.fullText ?: "",                uiElements = uiElements,                ocrBlocks = ocrResult?.value?.blocks ?: emptyList(),            )        } catch (t: Throwable) {            Timber.tag(TAG).e("LLM summarization failed", t)            // Fallback: template-based summary.            fallbackSummary(ocrResult?.value, uiElements)        }        val elapsedMs = System.currentTimeMillis() - startTime        Timber.tag(TAG).i("Screen read complete: ${uiElements.size} UI elements, ${elapsedMs}ms.")        ScreenUnderstandingResult(            summary = summary.summary,            spokenSummary = summary.spokenSummary,            ocrText = ocrResult?.value?.fullText ?: "",            uiElements = uiElements,            confidence = summary.confidence,            processingTimeMs = elapsedMs,        )    }    /**     * Find a specific UI element by text (e.g., "Send button", "Reply").     *     * @param searchText the text to search for.     * @return the matching UI element, or null if not found.     */    suspend fun findElement(searchText: String): UiElement? = withContext(dispatcher) {        if (!sessionActive) return@withContext null        val screenshot = screenshotCapturer.capture() ?: return@withContext null        val elements = uiElementDetector.detect(screenshot)        return@withContext elements.firstOrNull { element ->            element.text?.contains(searchText, ignoreCase = true) == true ||            element.label.contains(searchText, ignoreCase = true)        }    }    /**     * Read a specific region of the screen (e.g., "read Mom's message").     *     * @param region bounding box of the region to read (normalized 0-1).     * @return the text in that region, or null.     */    suspend fun readRegion(region: BoundingBox): String? = withContext(dispatcher) {        if (!sessionActive) return@withContext null        val screenshot = screenshotCapturer.capture() ?: return@withContext null        val ocrResult = ocrEngine.recognize(screenshot)        val blocks = ocrResult.value?.blocks ?: return@withContext null        // Filter blocks that overlap with the requested region.        val overlappingText = blocks            .filter { block -> blocksOverlap(block.boundingBox, region) }            .joinToString(" ") { it.text }        overlappingText.ifBlank { null }    }    /** True if screen reading is currently active. */    fun isSessionActive(): Boolean = sessionActive    /** True if consent is granted for the current session. */    fun isConsentGranted(): Boolean = consentGranted    // ─── Internal helpers ─────────────────────────────────────────────────    private fun fallbackSummary(ocrResult: OcrResult?, uiElements: List<UiElement>): ScreenSummary {        val elementCount = uiElements.size        val textPreview = ocrResult?.fullText?.take(100) ?: ""        val summary = if (elementCount > 0) {            "Found $elementCount UI elements. Text: $textPreview"        } else if (!textPreview.isBlank()) {            "Screen text: $textPreview"        } else {            "I can't read anything on this screen."        }        return ScreenSummary(            summary = summary,            spokenSummary = summary,            confidence = 0.5f,  // Low confidence for fallback.        )    }    private fun blocksOverlap(a: BoundingBox, b: BoundingBox): Boolean {        return !(a.right < b.left || a.left > b.right || a.bottom < b.top || a.top > b.bottom)    }    private companion object {        private const val TAG = "ScreenUnderstanding"    }}// ──────────────────────────────────────────────────────────────────────────/** Result of [ScreenUnderstandingEngine.readScreen]. */data class ScreenUnderstandingResult(    val summary: String,    val spokenSummary: String,    val ocrText: String,    val uiElements: List<UiElement>,    val confidence: Float,    val processingTimeMs: Long,) {    /** True if the screen has any readable content. */    val hasContent: Boolean get() = ocrText.isNotBlank() || uiElements.isNotEmpty()}/** LLM-generated summary of the screen. */data class ScreenSummary(    val summary: String,    val spokenSummary: String,    val confidence: Float,)// ──────────────────────────────────────────────────────────────────────────/** A detected UI element (button, icon, input field). */data class UiElement(    val label: String,        // "button", "input", "icon", "link"    val text: String?,        // Text on the element (e.g., "Send", "Reply")    val boundingBox: BoundingBox,    val confidence: Float,    val isInteractive: Boolean = true,) {    /** Human-readable description (for TTS). */    val description: String        get() = buildString {            append(label)            text?.let { append(" \"$it\"") }            append(" at ${boundingBoxPosition}")        }    /** Position description (e.g., "top left", "bottom right"). */    val boundingBoxPosition: String        get() {            val horizontal = when {                boundingBox.center.first < 0.33f -> "left"                boundingBox.center.first > 0.66f -> "right"                else -> "center"            }            val vertical = when {                boundingBox.center.second < 0.33f -> "top"                boundingBox.center.second > 0.66f -> "bottom"                else -> "middle"            }            return "$vertical $horizontal"        }    private val BoundingBox.center: Pair<Float, Float>        get() = Pair((left + right) / 2f, (top + bottom) / 2f)}// ──────────────────────────────────────────────────────────────────────────/** * Screenshot capturer interface — abstracts AccessibilityService. * * Production: [AccessibilityScreenshotCapturer] wraps NousAccessibilityService (Module 10). * Tests: [FakeScreenshotCapturer] returns canned images. */interface ScreenshotCapturer {    /** Capture the current screen as image bytes. */    suspend fun capture(): ByteArray?    /** True if the accessibility service is available + permission granted. */    fun isAvailable(): Boolean}/** * UI element detector interface — abstracts accessibility tree parsing. * * Production: [AccessibilityUiElementDetector] uses AccessibilityService. */interface UiElementDetector {    suspend fun detect(imageBytes: ByteArray): List<UiElement>}/** * Screen summarizer interface — produces a human-readable description. * * Production: [LlmScreenSummarizer] uses local LLM, [RealScreenSummarizer] uses heuristics. */interface ScreenSummarizer {    suspend fun summarize(        ocrText: String,        uiElements: List<UiElement>,        ocrBlocks: List<com.roshan.persona.vision.ocr.OcrBlock>,    ): ScreenSummary}